    public DesignMetrics() {}
    public int value(Role role) { return Objects.requireNonNull(role).value; }
    /** Minimum outer height accommodating actual font line metrics, without scaling logical catalog values. */
    public int contentHeight(Role height, Font font, FontRenderContext context) {
        Objects.requireNonNull(font); Objects.requireNonNull(context);
        int padding = switch (height) {
            case PICKER_COMPACT_HEIGHT,PICKER_DEFAULT_HEIGHT,PICKER_SEARCH_HEIGHT,PICKER_ROW_HEIGHT,PICKER_UTILITY_HEIGHT,FORM_SEGMENT_HEIGHT,FULL_SETTING_CHOICE_HEIGHT -> 4;
            case PANEL_SEARCH_HEIGHT -> value(Role.PANEL_SEARCH_VERTICAL_PADDING);
            case PANEL_HEADER_ACTION -> value(Role.PANEL_HEADER_ACTION_VERTICAL);
            case FIELD_HEIGHT, HERO_FIELD_HEIGHT, COLUMN_SEARCH_HEIGHT -> value(Role.FIELD_VERTICAL_PADDING);
            case PANEL_EMPTY_ACTION_HEIGHT, SETTINGS_NAV_HEADING, SETTINGS_NAV_ROW, KEYCAP_TREE_ROW_HEIGHT, IDENTITY_ROW_HEIGHT, IDENTITY_HEADING_HEIGHT, MENU_ITEM_HEIGHT, BUTTON_HEIGHT, HERO_BUTTON_HEIGHT, FULL_FOOTER_BUTTON_HEIGHT, ORDERED_ADD_HEIGHT, PANEL_ACTION, INLINE_ACTION -> value(Role.BUTTON_VERTICAL_PADDING);
            case PANEL_DETAIL_ACTION -> value(Role.PANEL_DETAIL_ACTION_VERTICAL);
            default -> throw new IllegalArgumentException("Not a content height role: " + height);
        };
        return Math.max(value(height), (int)Math.ceil(font.getLineMetrics("Ag", context).getHeight()) + padding);
    }
